import {rapidBuildScenes} from './rapid-build-cases.js';
const delivery='d13-delivery-dependencies', interfaces='d13-interface-contracts', acceptance='d13-commissioning-complete-paths';
const c=(key,label,options)=>({key,label,options});
const s=(id,label,title,reference,objective,explanation,extra={})=>({id,label,title,reference,objective,pedagogical_role:'mechanism',explanation:[explanation],...extra});
export const learningContract=Object.freeze({driving_question:'How does a design become a tested, usable service?',fixed_boundary:'A 20 MW IT phase in ten 2 MW zones, ending at integrated service acceptance.',changed_variable:'Delivery dependencies, manufacturing release, rack density and acceptance scope.',primary_payoff:'Release work against approved interfaces and count complete accepted paths.',misconception:'Unchanged total MW means unchanged interfaces and delivery dates.',closing_question:'Which revised racks can operate, and which evidence is still missing?'});
export const initialState={intervention:'baseline',factoryWeeks:6,approvalWeek:0,factorySlotWeek:0,boundary:'coolant',rackKW:200,action:'unconfirmed',testPhase:'fault',coolingStart:21,electrical:false,hydraulic:false,geometry:false,logistics:false,controls:false,resources:false,diagnosis:'',showDiagnosis:false};
export const scenes=[
 s('delivery-purpose','Design, procurement and commissioning','How does a design become a usable service?',delivery,'D13.1','The endpoint is an accepted service path. Follow a 20 MW IT phase through dependencies, changed interfaces and acceptance.',{pedagogical_role:'problem'}),
 s('rack-change','The late rack change','The phase stays at 20 MW. Each rack connection changes.',interfaces,'D13.2','Ten 2 MW zones change from twenty 100 kW racks per zone to ten 200 kW racks. Hold IT duty fixed; auxiliary demand, current, hydraulic pressure, geometry and local loads still require review.',{pedagogical_role:'problem'}),
 s('hardware-prices-meme','AI demand and hardware prices','AI demand and hardware prices',delivery,'D13.1','User-supplied hardware-price meme retained from the retired storage deck.',{pedagogical_role:'transition',imageOnly:true}),
 s('service-requirements','Define the finish','The finish line is a working rack, including during a cooling fault.',interfaces,'D13.2','The owner requirement states intended behavior; the design basis explains how the system meets it; acceptance makes it observable. Ten 2 MW zones require electrical, thermal and information paths to the same racks.'),
 s('critical-path','Which delay matters?','Which earlier delivery would let testing start sooner?',delivery,'D13.1','Baseline 27; cooling four weeks faster still 27; electrical four weeks faster 23; cooling eight weeks later 28; utility ready week 30 gives 34. Installation and test resources must be available at the changed dates.',{pedagogical_role:'comparison',controls:[c('intervention','Change one input',[['baseline','Baseline'],['cooling-fast','Cooling −4 wk'],['electrical-fast','Electrical −4 wk'],['cooling-late','Cooling +8 wk'],['utility-late','Utility → wk 30']])]}),
 s('epc-and-prefab','Responsibilities and manufacturing','EPC assigns responsibility. Prefabrication locates the work.',delivery,'D13.2','Engineering, procurement and construction are delivery responsibilities. This example assigns design coordination, purchases, site works and integration to one EPC team. It can choose site assembly, factory modules or both. Actual contracts assign the duties.'),
 s('factory-and-site','Factory and site work','A service module moves assembly into the factory.',delivery,'D13.2','Both routes use manufactured components. Prefabrication assembles distribution, manifolds, internal wiring and controls into transportable frames. The site still delivers access, foundations, utilities, placement, field joints, IT racks and integrated acceptance.'),
 {...rapidBuildScenes.find(item=>item.id==='aws-houdini-prefab'),title:'Project Houdini moves data-hall assembly into factories.',objective:'D13.1'},
 s('parallel-schedules','Overlap the work','Factory work can run while the site is prepared.',delivery,'D13.1','Week zero means approved interfaces and available components. Site enabling 8 weeks; site assembly 6; factory assembly initially 6; transport 1; connections 2; acceptance 2. Site-built 16; prefab max(factory+1,8)+2+2, initially 12. These exercise durations do not describe Houdini.',{pedagogical_role:'comparison',controls:[c('factoryWeeks','Factory assembly + checks',[[6,'6 weeks'],[9,'9 weeks'],[12,'12 weeks']])]}),
 s('manufacturing-release','Freeze the interfaces','The factory needs the final connection drawing before it drills.',interfaces,'D13.2','Approve ratings, dimensions, connection locations, signal definitions and drawing revisions before cutting or assembling affected work. Release independent packages only when approved boundaries establish independence. Design approval does not reserve factory capacity.'),
 s('module-transport','Transport and placement','The module must fit the route and the installation.',delivery,'D13.2','Use actual shipping dimensions, mass, center of gravity, lifting points, route limits and placement access. In this exercise IT racks are installed after shipment; doubled installed rack mass does not automatically double module shipping mass.'),
 s('compass-package','Siemens and Compass','One factory package still has site interfaces.',interfaces,'D13.2','Siemens and Compass co-developed a medium-voltage skid with 8DJH 36 switchgear and a transformer. The factory photo shows switchgear, not the transformer. The responsibility questions are teaching prompts, not claims about Compass contractual scope.',{pedagogical_role:'case-study',sources:['https://www.siemens.com/en-us/company/insights/compass-datacenters-case-study/']}),
 s('interface-owner','Own the joint','Two suppliers must agree where their parts meet.',interfaces,'D13.2','The exercise assigns closure to the EPC interface manager. Module supplier owns internal assemblies; site contractor owns field connections; design leads approve adequacy. Both technical sides agree the joint, then commissioning verifies the installed result.',{controls:[c('boundary','Inspect a boundary',[['electrical','Electrical'],['coolant','Coolant'],['structure','Base and joints'],['controls','Controls']])]}),
 s('electrical-interface','Check each electrical branch','Each new rack needs twice the current through its branch.',interfaces,'D13.2','Balanced 480 V three-phase, PF 1, one full-duty supply path. 120.3 A at 100 kW becomes 240.6 A at 200 kW, beyond the old allowable continuous 160 A. Review the revised ratings, one-line, protection and failure states.'),
 s('hydraulic-interface','Check flow and pressure','Each new rack needs twice the flow through its branch.',interfaces,'D13.2','All IT heat enters water, cp 4.18 kJ/(kg·K), rise at most 10 K. 2.39 becomes 4.78 kg/s; old branch limit 3.0. Reused hardware has quadratic pressure-flow behavior: 20 becomes 80 kPa, beyond 60 available. Actual pump and component curves release the redesign.'),
 s('spatial-interface','Check the occupied position','The same total weight can put twice the load on each foot.',interfaces,'D13.2','The vendor drawing stipulates twice the installed mass on the same four feet, equally shared. Half as many racks preserves zone mass but doubles occupied-position and foot loads. Check supports, anchorage, connection positions, service clearance and replacement routes.'),
 s('release-holds','Release each package','The site can continue while the changed connections wait.',interfaces,'D13.2','Controls represent completed approvals. Electrical and hydraulic fabrication also need coordinated geometry. The logistics checkbox approves the transport plan only; actual shipment still requires factory release. Resources must be confirmed to support the schedule. Service acceptance remains outstanding.',{pedagogical_role:'transfer'}),
 s('approval-delay','Recalculate the date','A late connection drawing can use up the time saved in the factory.',delivery,'D13.1','Factory 6 weeks; transport 1; site ready 8; connections 2; acceptance 2. Approval week 0 gives finish 12; approval 3 gives 14; approval 5 gives 16. Start waits for the available factory slot. Site-built remains 16 while approvals precede week 8.',{controls:[c('approvalWeek','Interfaces approved',[[0,'Week 0'],[3,'Week 3'],[5,'Week 5']]),c('factorySlotWeek','Factory capacity available',[[0,'On approval'],[7,'Week 7']])]}),
 s('controls-interface','Prove the action path','Did the cooling-fault command reach the right rack?',interfaces,'D13.2','A cooling-fault signal must identify the rack, have defined units and freshness, reach an authorized action and provide observed confirmation. Remap alarms, circuits and reduction groups for the revised racks. The example does not prescribe a live operating procedure.',{controls:[c('action','Load reduction request',[['unconfirmed','No response confirmed'],['confirmed','Response measured']])]}),
 s('factory-acceptance','Factory acceptance tests','A factory test covers the assembly that was tested.',acceptance,'D13.3','FAT means factory acceptance test. It can check internal wiring, plumbing and controls against agreed criteria. Site cables, coolant joints and the final load path remain outside a test where those objects are absent. Shipment release and service acceptance have different evidence.'),
 s('integrated-tests','Integrated acceptance','A failure test must show the required response at the rack.',acceptance,'D13.4','Follow one agreed cooling failure through physical fault, authorized command and measured response. Define numerical requirements, measurement points, response time and stop/accept criteria before execution. Normal duty, maintenance and recovery still need tests; their scenarios remain in the reader. Facilities test loads and application tests establish different evidence.',{controls:[c('testPhase','Follow the failure test',[['fault','1. Cooling fault'],['command','2. Command'],['measured','3. Measured response']])]}),
 s('accepted-paths','Count complete paths','The accepted systems must reach the same racks.',acceptance,'D13.3','Continue with the revised 100 racks at 200 kW, totaling 20 MW. Electrical acceptance covers A01–A80, cooling A21–A100 and network A01–A60. Their overlap is 40 racks, or 8 MW, assuming all other acceptance criteria met. Cooling extended to A01 gives 60 racks and 12 MW.',{controls:[c('coolingStart','Cooling acceptance',[[21,'A21–A100'],[1,'A01–A100']])]}),
 s('phase-boundary','Build beside an operating phase','A new phase can change a shared operating system.',acceptance,'D13.4','Teaching topology: A and future B share upstream plant and controls. Define live/construction boundaries, isolation ownership, shared capacity and required retests before connecting B. A prior acceptance record does not automatically accept a changed shared configuration.'),
 s('release-decision','Chapter 13 knowledge check','Which racks can operate now?',acceptance,'D13.4','The revised racks draw 200 kW each. Electrical A01–A80, cooling A21–A100 and network A01–A60 overlap at A21–A60. Only A21–A40 have a measured cooling-fault response that meets the agreed limits and timing. A41–A60 have a command acknowledgement but no confirmed rack response. All other acceptance criteria are met and operating records match the tested revision. Accept A21–A40: 20 racks and a 4 MW envelope. A41–A60 still need a measured response that passes. A01–A20 still need cooling evidence; A61–A100 still need network evidence, and A81–A100 also need electrical evidence. Handover includes the tested asset map, protection and control versions, limits, procedures, maintenance responsibilities, training and explicit disposition of open issues.',{pedagogical_role:'transfer'}),
];

export const sceneAliases=Object.freeze({
 'delivery-paths':'critical-path',
 'site-checks':'factory-acceptance',
 'handover-records':'release-decision',
});
export function resolveProcurementScene(hash){
 const id=sceneAliases[hash]||hash;
 const index=scenes.findIndex(scene=>scene.id===id);
 return index<0?0:index;
}
